rd s10-span-7"><h2>Primary Backup Policy</h2><form method="post"><input type="hidden" name="csrf" value="<?= backup_step18_h($csrf) ?>"><label style="display:flex;gap:10px;align-items:center;font-weight:800;margin:10px 0"><input type="checkbox" name="is_enabled" value="1" <?= !empty($policy['is_enabled'])?'checked':'' ?>> Scheduled backup policy enabled</label><label style="display:block;font-weight:800;margin-top:12px">Frequency<select name="frequency_code" style="width:100%;padding:10px;margin-top:5px;border:1px solid #cedbd2;border-radius:10px"><option value="daily" <?= $policy['frequency_code']==='daily'?'selected':'' ?>>Daily</option><option value="weekly" <?= $policy['frequency_code']==='weekly'?'selected':'' ?>>Weekly</option></select></label><label style="display:block;font-weight:800;margin-top:12px">Preferred Time<input type="time" name="preferred_time" value="<?= backup_step18_h(substr((string)$policy['preferred_time'],0,5)) ?>" required style="width:100%;box-sizing:border-box;padding:10px;margin-top:5px;border:1px solid #cedbd2;border-radius:10px"></label><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px"><label style="font-weight:800;margin-top:12px">Daily Copies<input type="number" name="retention_daily" min="1" max="90" value="<?= (int)$policy['retention_daily'] ?>" style="width:100%;box-sizing:border-box;padding:10px;margin-top:5px;border:1px solid #cedbd2;border-radius:10px"></label><label style="font-weight:800;margin-top:12px">Weekly Copies<input type="number" name="retention_weekly" min="1" max="52" value="<?= (int)$policy['retention_weekly'] ?>" style="width:100%;box-sizing:border-box;padding:10px;margin-top:5px;border:1px solid #cedbd2;border-radius:10px"></label><label style="font-weight:800;margin-top:12px">Monthly Copies<input type="number" name="retention_monthly" min="1" max="60" value="<?= (int)$policy['retention_monthly'] ?>" style="width:100%;box-sizing:border-box;padding:10px;margin-top:5px;border:1px solid #cedbd2;